<?php
require_once __DIR__.'/auth.php';require_once __DIR__.'/../workflow_support.php';require_once __DIR__.'/../account_security.php';
if($_SESSION['role']!=='admin'){http_response_code(403);exit('Administrator access required.');}
$error='';$username=is_string($_REQUEST['username']??null)?trim($_REQUEST['username']):'';$target=null;
if($username!==''){$q=$pdo->prepare('SELECT * FROM users WHERE username=?');$q->execute([$username]);$target=$q->fetch(PDO::FETCH_ASSOC);}
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  if(!is_string($_POST['csrf_token']??null)||!hash_equals($_SESSION['admin_notification_csrf'],$_POST['csrf_token'])){http_response_code(403);throw new InvalidArgumentException('Reload this page before changing access.');}
  if(!$target||$target['role']==='admin')throw new InvalidArgumentException('Choose a staff or resident account. Administrator access is protected.');
  $action=$_POST['action']??'';$pdo->beginTransaction();
  if($action==='reset'){
   $password=is_string($_POST['password']??null)?$_POST['password']:'';
   if(strlen($password)<8||strlen($password)>72||$password!==($_POST['password_confirmation']??''))throw new InvalidArgumentException('Enter a temporary password of 8–72 bytes with matching confirmation.');
   $q=$pdo->prepare('UPDATE users SET password=?,must_change_password=1,session_version=session_version+1 WHERE id=?');$q->execute([password_hash($password,PASSWORD_DEFAULT),$target['id']]);
   $q=$pdo->prepare('DELETE FROM password_reset_tokens WHERE user_id=?');$q->execute([$target['id']]);accountActivity($pdo,$target,'Administrator issued a temporary password for account recovery.');
  }elseif(in_array($action,['deactivate','activate'],true)&&$target['role']==='staff'){
   $q=$pdo->prepare('UPDATE users SET is_active=?,session_version=session_version+1 WHERE id=?');$q->execute([$action==='activate'?1:0,$target['id']]);accountActivity($pdo,$target,$action==='activate'?'Staff account reactivated.':'Staff account deactivated; previous activity preserved.');
  }else throw new InvalidArgumentException('Choose a valid account action.');
  $pdo->commit();header('Location: account_access.php?username='.rawurlencode($username).'&saved=1');exit;
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();if(http_response_code()!==403)http_response_code(422);$error=$e instanceof InvalidArgumentException?$e->getMessage():'Unable to update account access.';}
}
$history=$pdo->query('SELECT * FROM account_activity ORDER BY id DESC LIMIT 50')->fetchAll(PDO::FETCH_ASSOC);
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Account access — Barangay Mudiang</title><link rel="stylesheet" href="../assets/vendor/bootstrap.min.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css"><?php include __DIR__.'/../ui_theme.php'; ?></head><body class="portal-page resident-directory"><?php include __DIR__.'/operations_nav.php'; ?><main class="main"><header class="topbar"><div class="topbar-left"><h1>Account access & recovery</h1><p>Keep access current and preserve accountability</p></div><a class="btn btn-outline" href="staff.php">Staff directory</a></header><div class="content">
<?php if($error): ?><div class="alert alert-danger" role="alert"><?= reportActivityEscape($error) ?></div><?php endif; ?><?php if(isset($_GET['saved'])): ?><div class="alert alert-success" role="status">Account access updated. Share any temporary password privately after verifying the account holder's identity.</div><?php endif; ?>
<section class="card mb-4"><div class="card-header"><h2>Find an account</h2></div><form method="get" class="card-body"><label for="recovery-user">Exact staff or resident username</label><div class="d-flex gap-2"><input class="form-control" id="recovery-user" name="username" value="<?= reportActivityEscape($username) ?>" required maxlength="50"><button class="btn btn-primary">Find</button></div></form></section>
<?php if($username!==''&&!$target): ?><p>No account matches this username.</p><?php endif; ?>
<?php if($target): ?><section class="card mb-4"><div class="card-header"><h2><?= reportActivityEscape($target['full_name']) ?> · @<?= reportActivityEscape($target['username']) ?></h2></div><div class="card-body"><p><?= ucfirst($target['role']) ?> · <?= $target['is_active']?'Active':'Inactive' ?></p><?php if($target['role']==='admin'): ?><p>Administrator access cannot be changed here.</p><?php else: ?>
<form method="post"><input type="hidden" name="csrf_token" value="<?= reportActivityEscape($_SESSION['admin_notification_csrf']) ?>"><input type="hidden" name="username" value="<?= reportActivityEscape($username) ?>"><p>Verify the person's identity before issuing a temporary password. They must replace it at their next sign-in.</p><div class="row g-3"><?php foreach(['password'=>'Temporary password','password_confirmation'=>'Confirm temporary password'] as $key=>$label): ?><div class="col-md-6"><label for="<?= $key ?>"><?= $label ?></label><input class="form-control" type="password" id="<?= $key ?>" name="<?= $key ?>" required minlength="8" maxlength="72" autocomplete="new-password"></div><?php endforeach; ?><div class="col-12"><button class="btn btn-primary" name="action" value="reset">Issue temporary password</button></div></div></form>
<?php if($target['role']==='staff'): ?><form method="post" class="mt-4"><input type="hidden" name="csrf_token" value="<?= reportActivityEscape($_SESSION['admin_notification_csrf']) ?>"><input type="hidden" name="username" value="<?= reportActivityEscape($username) ?>"><p>Deactivation blocks sign-in and revokes current sessions. Existing report history remains available.</p><button class="btn btn-outline" name="action" value="<?= $target['is_active']?'deactivate':'activate' ?>"><?= $target['is_active']?'Deactivate staff account':'Reactivate staff account' ?></button></form><?php endif;endif; ?></div></section><?php endif; ?>
<section class="card"><div class="card-header"><h2>Account access history</h2></div><div class="table-wrap"><table><thead><tr><th>Recorded at</th><th>Performed by</th><th>Account</th><th>Action</th></tr></thead><tbody><?php foreach($history as $event): ?><tr><td><?= reportActivityEscape($event['created_at']) ?></td><td><?= reportActivityEscape($event['actor_name']) ?></td><td><?= reportActivityEscape($event['target_name']) ?></td><td><?= reportActivityEscape($event['summary']) ?></td></tr><?php endforeach;if(!$history): ?><tr><td colspan="4">No account access changes recorded yet.</td></tr><?php endif; ?></tbody></table></div></section>
</div></main><?php include __DIR__.'/notification_widget.php'; ?></body></html>
